{
  "implementation": "def solve(case):
    # extract inputs
    passing = case['passing']
    failing = case['failing']
    required = case['required_difference']
    unresolved = case.get('unresolved_difference', [])

    # compute ordered change set (failing \ passing)
    changes = []
    seen = set(passing)
    for x in failing:
        if x not in seen:
            changes.append(x)

    test_count = [0]  # mutable integer for closure

    # oracle: returns 'FAIL', 'PASS', or 'UNRESOLVED'
    def oracle(subset):
        test_count[0] += 1
        # unresolved check
        for elem in subset:
            if elem in unresolved:
                return 'UNRESOLVED'
        # fail if subset contains all required elements
        for req in required:
            if req not in subset:
                return 'PASS'
        return 'FAIL'

    # initial test on the full change set
    if oracle(changes) != 'FAIL':
        return {'isolated_difference': [], 'tests': test_count[0]}

    # ddmin implementation (iterative)
    c = changes[:]
    n = 2
    while len(c) >= 2:
        # split into n contiguous chunks
        chunk_size = (len(c) + n - 1) // n
        subsets = []
        for i in range(0, len(c), chunk_size):
            subsets.append(c[i:i+chunk_size])

        reduced = False
        # test each subset
        for subset in subsets:
            res = oracle(subset)
            if res == 'FAIL':
                c = subset
                n = max(2, n - 1)
                reduced = True
                break
        if reduced:
            continue

        # test complements of subsets
        for subset in subsets:
            # complement = all other chunks concatenated
            complement = []
            for s in subsets:
                if s is not subset:
                    complement.extend(s)
            res = oracle(complement)
            if res == 'FAIL':
                c = complement
                n = max(2, n - 1)
                reduced = True
                break
        if reduced:
            continue

        # increase granularity
        if n == len(c):
            break
        n = min(2 * n, len(c))

    return {'isolated_difference': c, 'tests': test_count[0]}
